import * as A from './amounts.mjs';
import {parseDate,displayDate} from './calendar.mjs';
import * as R from './rules.mjs';
import * as S from './state.mjs';
import * as M from './map.mjs';
import {createWorldPicker,rememberWorld} from './world-picker.mjs';
import {Store,KEY} from './persistence.mjs';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ROOT='https://github.com/OwlsNestNH/Traveller-Tools/blob/main/tools/trade-route-calculator/';
const money=x=>'Cr '+String(x).replace(/\B(?=(\d{3})+(?!\d))/g,','),field=(name,label,value='',type='text',extra='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,options,value)=>`<label class="field">${esc(label)}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const check=(name,label,value=false)=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${esc(label)}</label>`;
const btn=(label,action,arg='',mutate=false,cls='')=>`<button class="${cls}" data-action="${action}" data-arg="${esc(arg)}" ${mutate?'data-mutate':''}>${esc(label)}</button>`;
const empty=text=>`<div class="empty">${text}</div>`,panel=(title,body,actions='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2><div class="row">${actions}</div></div>${body}</section>`;
const saleQuotes=new Map();
let showHexes=true,mapZoom=1,mapZoomFrame=0;
let core,mp,decisions,state=S.initial(),store,known={},view=null,tab='Overview',snapshotId=null,marketFilter='active',marketSearch='',cargoSearch='',cargoSort='name',selected=new Set(),contractDrafts=[],modalRevision=0,modalGeneration=0,previewSale=null;
function world(id){return state.worlds[id]||known[id];}function good(id){return core.commodities.find(g=>g.id===id);}function ctx(id){return R.context(world(id),core);}function viewed(){return world(view||state.actual);}function actual(){return world(state.actual);}function partyKey(id,name){return id+'|'+name.trim().toLowerCase();}
function message(text,error=false){$('message').textContent=text;$('message').className='visible'+(error?' error':'');}
function safely(fn){return async(...args)=>{try{return await fn(...args);}catch(e){message(e.message,true);}};}
function modal(title,body,submit,label='Save'){modalGeneration++;modalRevision=state.revision;$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal-error').textContent='';$('modal-submit').textContent=label;$('modal-submit').hidden=!submit;$('modal-cancel').textContent=submit?'Cancel':'Close';$('modal-form').onsubmit=async e=>{e.preventDefault();const generation=modalGeneration;const data=new FormData(e.currentTarget);$('modal-submit').disabled=true;try{const result=await submit(data);if(result!==false&&generation===modalGeneration)$('modal').close();}catch(err){$('modal-error').textContent=err.message;}finally{$('modal-submit').disabled=false;}};if(!$('modal').open)$('modal').showModal();}
function act(label,fn,expected=($('modal').open?modalRevision:state.revision)){if(expected!==state.revision)throw Error('Campaign changed. Reopen this preview before committing.');const next=S.transition(state,label,s=>{s.worlds={...known,...s.worlds};fn(s);});store.save(next,expected);message(label+' saved.');return next;}
function audit(title,data){modal(title,`<p class="help">Frozen inputs and calculation results. <a href="${ROOT}OPTIONAL_RULES.md#additional-decisions-approved-2026-10-03" target="_blank" rel="noopener">Insurance / tax interpretations</a> · <a href="${ROOT}RULES_REVIEW.md#interpretation-decision-register" target="_blank" rel="noopener">Core interpretations</a> · <a href="${ROOT}RULES_VERIFICATION.md" target="_blank" rel="noopener">Rules verification</a> · ${btn('Rules & Notes','notes')}</p><pre>${esc(JSON.stringify(data,null,2))}</pre>`,null);}
function table(headers,rows,cls=''){return `<div class="scroll ${cls}"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function render(){if(!core)return;if(view&&!world(view))view=state.actual;selected=new Set([...selected].filter(id=>state.lots.some(l=>l.id===id)));$('summary').innerHTML=[['Ship',state.ship.name],['Bank',money(state.bank)],['Cargo',A.decimal(S.used(state))+' / '+state.ship.capacity+' t'],['Actual location',actual()?.name||'Not set'],['Campaign time',displayDate(state.dateLabel,state.hours)]].map(([l,v])=>`<div class="stat"><span class="label">${esc(l)}</span><span class="value ${l==='Bank'?'mono':''}">${esc(v)}</span></div>`).join('');$('tabs').innerHTML=['Overview','Cargo','Contracts','Accounts','History','Settings'].map(t=>btn(t,'tab',t,false,tab===t?'active':'')).join('');if(store?.recovery){$('main').innerHTML=panel('Recover saved campaign',`<div class="panel-body"><p class="notice">${esc(store.recoveryMessage||'Saved data needs recovery.')}</p><p>The saved data has not been replaced. Export its raw contents before importing a valid backup or resetting.</p><div class="wide-actions">${btn('Export raw saved data','export')}${btn('Import backup','import','',true)}${btn('Reset campaign','reset','',true,'danger')}</div></div>`);}else if(!state.initialized){$('main').innerHTML=`<section class="panel welcome"><span class="eyebrow">YOUR NEXT TRADE STARTS HERE</span><h2>Bring your campaign aboard.</h2><p class="muted">Set your current world, ship and bank balance. Add cargo you already own without buying it again. Your campaign stays in this browser; export a backup whenever you need one.</p><div class="wide-actions">${btn('Set up campaign','setup','',true,'primary')}${btn('Import campaign','import')}</div><p class="help">Free static tool · Traveller Map world data · Core Rulebook Update 2022 · Optional Merchant Prince insurance and taxes</p></section>`;}else if(tab==='Overview')$('main').innerHTML=`<div class="grid"><div>${mapPanel()}</div><div>${marketPanel()}${cargoPanel(false)}</div></div>`;else if(tab==='Cargo')$('main').innerHTML=cargoPanel(true)+policyPanel();else if(tab==='Contracts')$('main').innerHTML=contractsPanel();else if(tab==='Accounts')$('main').innerHTML=accountsPanel();else if(tab==='History')$('main').innerHTML=historyPanel();else $('main').innerHTML=settingsPanel();document.querySelectorAll('[data-mutate]').forEach(b=>b.disabled=!store?.editable||b.hasAttribute('data-unavailable'));}
function mapHexGrid(w,point,scale){
 if(!showHexes)return '';
 const radius=scale/Math.sqrt(3),cells=[];
 for(let dx=-12;dx<=12;dx++)for(let dy=-13;dy<=13;dy++){
  const x=w.x+dx,y=w.y+dy;if(M.distance(w,{x,y})>12)continue;const [cx,cy]=point({x,y});
  if(cx < -radius||cx>520+radius||cy < -radius||cy>320+radius)continue;
  const corners=Array.from({length:6},(_,i)=>[cx+radius*Math.cos(i*Math.PI/3),cy+radius*Math.sin(i*Math.PI/3)].join(',')).join(' ');
  const hx=((Number(w.hex.slice(0,2))-1+dx)%32+32)%32+1,hy=((Number(w.hex.slice(2))-1+dy)%40+40)%40+1;
  const hex=String(hx).padStart(2,'0')+String(hy).padStart(2,'0');
  cells.push(`<polygon data-hex="${hex}" points="${corners}"/>${scale>=24?`<text x="${cx}" y="${cy+13}" text-anchor="middle">${hex}</text>`:''}`);
 }
 return '<g class="hex-grid" aria-hidden="true">'+cells.join('')+'</g>';
}
function mapPanel(){const w=viewed();if(!w)return '';const worlds=Object.values({...known,...state.worlds}).filter(x=>M.distance(x,w)<=12);const cx=260,cy=158,scale=50*mapZoom;const point=x=>[cx+(x.x-w.x)*scale*Math.sqrt(3)/2,cy+((x.y+((x.x%2+2)%2)*.5)-(w.y+((w.x%2+2)%2)*.5))*scale];const route=state.route.map(id=>world(id)).filter(Boolean);const path=route.map(x=>point(x).join(',')).join(' ');let info;try{const c=ctx(w.id);info=`<span class="mono">${esc(c.uwp.raw)}</span><div class="badge-row">${c.codes.map(x=>`<span>${x}</span>`).join('')}${c.unknown.length?'<span>Incomplete UWP</span>':''}</div>`;}catch(e){info=`<p class="bad">${esc(e.message)}</p>`;}const svg=`<svg class="world-map" viewBox="0 0 520 320" role="img" aria-label="Clickable local world map"><defs><pattern id="stars" width="37" height="43" patternUnits="userSpaceOnUse"><circle cx="7" cy="13" r=".6" fill="#376076"/></pattern></defs><rect width="520" height="320" fill="url(#stars)"/>${mapHexGrid(w,point,scale)}<polyline points="${path}" fill="none" stroke="#62d3dd" stroke-width="1.5" opacity=".55"/>${worlds.map(x=>{const[p,q]=point(x);return `<g role="button" tabindex="0" aria-label="Browse ${esc(x.name)}" data-action="world" data-arg="${x.id}"><title>${esc(x.name)} · ${esc(x.hex)}</title><circle cx="${p}" cy="${q}" r="${x.id===state.actual?(scale<24?4:7):(scale<24?2:4)}" fill="${x.id===state.actual?'#62d3dd':x.zone==='Red'?'#ff959e':x.zone==='Amber'?'#f5bd6c':'#9bb7ce'}" stroke="${x.id===w.id?'#fff':'#172e40'}" stroke-width="${x.id===w.id?2:1}"/>${scale>=24||x.id===state.actual||x.id===w.id?`<text x="${p+10}" y="${q+4}">${esc(x.name)}</text>`:''}</g>`;}).join('')}</svg>`;const next=world(state.route[state.routeIndex+1]);return panel('Navigation',`<div class="panel-body"><div class="toolbar">${btn('Find world','find')}${btn('Plot route','route','',true)}${btn('Refresh nearby','nearby')}${btn('Current ship','world',state.actual)}<label class="check"><input type="checkbox" id="map-hexes" ${showHexes?'checked':''}>Show hexes</label></div><span class="help">${esc(w.sector)} · ${esc(w.hex)} · viewing ${w.id===state.actual?'actual location':'another world'}</span></div><div class="map-zoom-controls" role="group" aria-label="Map zoom">${btn('−','map-zoom-out')}${btn('+','map-zoom-in')}${btn('Reset view','map-zoom-reset')}<span class="help" aria-live="polite">${Math.round(mapZoom*100)}%</span></div>${svg}<div class="world-info"><div class="row"><strong>${esc(w.name)}</strong><span class="tag ${w.zone==='Red'?'illegal':w.zone==='Amber'?'amber':''}">${esc(w.zone)}</span></div>${info}<div class="row">${w.id!==state.actual?btn('Use as starting world','set-location',w.id,true,'small'):''}${btn('World override','override',w.id,true,'small')}<span class="help">Fuel: ${M.fuel(w,state.ship,core)?'available':'unconfirmed / unavailable'}</span></div></div><div class="route-list">${state.route.map((id,i)=>btn((i+1)+'. '+world(id)?.name,'world',id,false,(id===state.actual?'current ':'')+(i<state.routeIndex?'done':''))).join('<span class="muted">›</span>')||'<span class="help">Plot a route to choose your next jump.</span>'}</div><div class="jump-bar"><div class="row">${btn('Previous','browse-prev')}${btn('Next','browse-next')}</div>${next?btn('COMMIT JUMP → '+next.name,'jump','',true,'primary'):'<span class="help">No next jump planned</span>'}</div><div class="map-hint">Scroll over the map to zoom; +, − and Reset view also work. Centered on the viewed world, showing nearby worlds within 12 parsecs. Hex numbers are local to each sector. Browsing never moves the ship. Route search uses loaded worlds, with fuel availability checks.</div>`);}

function tradeTable(kind,headers,widths,rows,cls=''){
 return '<div class="scroll '+cls+'"><table class="trade-table '+kind+'-table"><colgroup>'+widths.map(w=>'<col style="width:'+w+'px">').join('')+'</colgroup><thead><tr>'+headers.map((h,i)=>'<th scope="col" class="'+([1,2,3,4].includes(i)&&kind!=='freight'||kind==='freight'&&[1,3,4].includes(i)?'number':'')+'">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';
}
function retail(commodity){const value=good(commodity)?.baseCreditsPerTon;return value==null?'Referee':money(value)+' / t';}
function currentQuote(id){const q=saleQuotes.get(id);return q&&q.worldId===state.actual&&q.revision===state.revision?q:null;}
function lotAudit(id){const lot=state.lots.find(l=>l.id===id);audit('Cargo lot', {lot,saleQuote:currentQuote(id)||'Not negotiated in this view',sourceSnapshot:state.snapshots.find(s=>s.id===lot?.snapshotId)});}

function marketPanel(){const id=viewed()?.id;const snapshots=state.snapshots.filter(s=>s.worldId===id&&s.kind!=='buyer');let snap=snapshots.find(s=>s.id===snapshotId)||snapshots.at(-1);const offers=(snap?.offers||[]).filter(o=>(marketFilter==='all'||marketFilter==='expired'&&o.expired||marketFilter==='active'&&!o.expired||marketFilter==='illegal'&&o.illegal)&&(good(o.commodity)?.name+' '+o.description).toLowerCase().includes(marketSearch.toLowerCase()));const rows=offers.map(o=>`<tr class="${o.expired?'expired-row':''}"><td>${esc(good(o.commodity)?.name)}${o.description&&o.description!==good(o.commodity)?.name?'<div class="help">'+esc(o.description)+'</div>':''}${o.illegal?'<span class="tag illegal">Illegal</span>':''}${o.manualRequired?'<span class="tag">Referee</span>':''}</td><td class="number">${esc(o.remaining)} t</td><td class="number">${retail(o.commodity)}</td><td class="number">${o.audit?.percent==null?'—':esc(o.audit.percent)+'%'}</td><td class="number">${money(o.unitPrice)} / t</td><td><span class="offer-status">${o.expired?'Expired':'Active'}</span><label class="check"><input type="checkbox" data-expire="${o.id}" ${o.expired?'checked':''} ${!store.editable?'disabled':''}>Expired</label></td><td class="table-actions">${btn('Buy','buy',o.id,true,'small').replace('<button', '<button '+(o.expired||o.manualRequired?'data-unavailable disabled':''))}${btn('Audit','offer-audit',o.id,false,'small')}${btn('Edit','offer-edit',o.id,true,'small')}</td></tr>`);return panel('Market · '+esc(viewed()?.name||''),`<div class="panel-body"><div class="toolbar">${snapshots.length?`<select id="snapshot-select" aria-label="Market search history">${snapshots.map(s=>`<option value="${s.id}" ${s.id===snap?.id?'selected':''}>${esc(s.partyName)} · hour ${s.hours} · ${s.criminal?'Black market':'Legal market'}</option>`).join('')}</select>`:''}${btn('Find supplier','search','',true,'primary')}</div><div class="toolbar"><input id="market-search" aria-label="Search market" placeholder="Find a commodity…" value="${esc(marketSearch)}"><select id="market-filter" aria-label="Filter offers">${[['active','Active'],['all','All'],['expired','Expired'],['illegal','Illegal']].map(([v,l])=>`<option value="${v}" ${marketFilter===v?'selected':''}>${l}</option>`).join('')}</select><span class="help">${offers.length} / ${snap?.offers.length||0} offers</span></div></div>${rows.length?tradeTable('purchase',['Commodity','Available','Retail','Price %','Purchase Price','Offer Status','Actions'],[210,95,140,85,145,125,190],rows):empty('No matching offers. Find a supplier at your actual world to create a market.')}<div class="panel-body row">${snap?btn('Expire all','expire-all',snap.id,true,'small'):''}${snap?btn('Reject supplier’s deal','reject',snap.id,true,'small'):''}<span class="help">Offers stay active until explicitly expired or rejected.</span></div>`);}
function cargoPanel(full){
 let lots=state.lots.filter(l=>(l.description+' '+good(l.commodity)?.name).toLowerCase().includes(cargoSearch.toLowerCase()));
 lots.sort((a,b)=>cargoSort==='quantity'?-A.cmp(a.quantity,b.quantity):a.description.localeCompare(b.description));
 const rows=lots.map(l=>{const q=currentQuote(l.id);return `<tr><td><label class="check"><input type="checkbox" aria-label="Select ${esc(l.description)}" data-lot="${l.id}" ${selected.has(l.id)?'checked':''}>${esc(good(l.commodity)?.name)}</label>${l.illegal?'<span class="tag illegal">Illegal</span>':''}</td><td class="number">${esc(l.quantity)} t</td><td class="number">${retail(l.commodity)}</td><td class="number">${q?.audit.percent==null?'—':esc(q.audit.percent)+'%'}</td><td class="number">${q?money(q.unitPrice)+' / t':'<span class="help">Not negotiated</span>'}</td><td>${esc(l.description)}<div class="help">Lot ${esc(l.id)}<br>Cost basis: ${money(l.basis)}</div></td><td class="table-actions">${btn('Sell','lot-sell',l.id,true,'small')}${btn('Audit','lot-audit',l.id,false,'small')}${btn('Edit','lot-correct',l.id,true,'small')}</td></tr>`;});
 return panel(full?'Cargo hold':'Cargo aboard',`<div class="panel-body toolbar"><input id="cargo-search" aria-label="Search cargo" placeholder="Search cargo lots…" value="${esc(cargoSearch)}"><select id="cargo-sort" aria-label="Sort cargo"><option value="name">Name</option><option value="quantity" ${cargoSort==='quantity'?'selected':''}>Quantity</option></select><span class="help">${lots.length} / ${state.lots.length} lots</span></div>${rows.length?tradeTable('cargo',['Commodity','Tons Held','Retail','Price %','Sale Price','Lot / Description','Actions'],[210,100,140,85,145,230,190],rows,full?'large-scroll':'cargo-scroll'):empty('No cargo yet. Buy goods or add your campaign’s existing cargo.')}<div class="selected-preview row"><span>${selected.size} selected</span>${btn('Preview sale','sale','',true,'primary')}${btn('Add existing / referee cargo','add-lot','',true)}${!full?btn('View all '+state.lots.length+' lots','tab','Cargo'):''}</div><div class="panel-body help">Sale prices appear after negotiation at the actual world. Quotes are previews for this session and become stale after campaign changes; reopening a negotiation rolls a new price.</div>`);
}
function policyPanel(){return panel('Cargo insurance',state.policies.length?state.policies.map(p=>`<article class="contract-card"><div class="row"><h3>${esc(state.lots.find(l=>l.id===p.lotId)?.description||'Former cargo lot')}</h3><span class="tag">${esc(p.status)}</span></div><p>${p.coverage}% coverage · ${esc(p.remainingQuantity)} t remaining · destination ${esc(world(p.destination)?.name)} · premium ${money(p.premium)}</p><div class="row">${btn('Policy audit','policy-audit',p.id)}${btn('Loss / claim','claim',p.id,true)}${btn('Amend / close','amend',p.id,true)}</div></article>`).join(''):empty('Insurance is off by default. Enable it in Settings, then choose coverage in the purchase preview.'));}
function contractsPanel(){
 const contractTable=(items,draft=false)=>tradeTable('freight',['Freight Lot / Description','Tons','Destination','Rate / ton','Total Revenue','Due / Delivery Date','Status','Actions'],[225,90,170,145,145,195,170,230],items.map(c=>{
  const id=draft?c.offerId:c.id;let rate;try{rate=money(A.decimal(A.div(c.payment,c.quantity)))+' / t';}catch{const r=A.auditNumber(A.div(c.payment,c.quantity));rate='Cr '+r.numerator+' / '+r.denominator+' per t';}
  const due=c.dueHours==null?'No due date':'Due: '+displayDate(state.dateLabel,c.dueHours),date=c.deliveredHours==null?due:due+'<br>Delivered: '+displayDate(state.dateLabel,c.deliveredHours);
  return `<tr><td>${esc(c.description||c.type||c.kind)}<div class="help">${esc(c.kind==='mail'?'Mail contract':'Freight contract')} · ${esc(id)}</div></td><td class="number">${esc(c.quantity)} t</td><td>${esc(world(c.destination)?.name||c.destination)}</td><td class="number">${rate}</td><td class="number">${money(c.payment)}</td><td>${date}</td><td>${draft?'Available · unpaid':c.status==='delivered'?'Delivered · paid '+money(c.payout):'Accepted · unpaid'}</td><td class="table-actions">${draft?btn('Accept','contract-accept',id,true,'small'):c.status==='accepted'?btn('Deliver','deliver',id,true,'small'):''}${btn('Audit/View',draft?'draft-audit':'contract-audit',id,false,'small')}${draft?btn('Edit','draft-edit',id,true,'small'):''}</td></tr>`;
 }));
 return panel('Freight & mail',`<div class="panel-body toolbar">${btn('Find contracts','contracts-search','',true,'primary')}${btn('Manual contract','contract-manual','',true)}</div><p class="panel-body help">Freight and mail are transport contracts, separate from owned speculative cargo. Revenue is paid only on committed delivery. Edit available offers before acceptance; accepted terms remain auditable.</p>${state.contracts.length?contractTable(state.contracts):empty('No accepted contracts.') }`)+panel('Available contracts',contractDrafts.length?contractTable(contractDrafts,true):empty('Find contracts to generate offers.'))+policyPanel();
}
function editDraft(id){
 const c=contractDrafts.find(c=>c.offerId===id);if(!c)throw Error('Offer no longer available');
 modal('Edit contract offer',field('description','Freight lot / description',c.description||c.type||c.kind)+field('quantity','Tons',c.quantity)+field('payment','Total revenue · Cr',c.payment)+field('due','Due at elapsed campaign hour (blank for none)',c.dueHours??'')+field('reason','Required reason',''),f=>{
  if(state.revision!==modalRevision)throw Error('Campaign changed. Reopen this offer.');
  const reason=f.get('reason').trim(),quantity=A.positive(f.get('quantity')),payment=String(A.credit(f.get('payment'))),dueHours=f.get('due').trim()===''?null:Number(f.get('due'));
  if(!reason||A.cmp(payment,0)<0||dueHours!==null&&(!Number.isSafeInteger(dueHours)||dueHours<0))throw Error('Valid terms and reason required');
  const after={description:f.get('description'),quantity,payment,dueHours};
  const edited={...c,...after,overrides:[...(c.overrides||[]),{hours:state.hours,reason,before:{description:c.description||'',quantity:c.quantity,payment:c.payment,dueHours:c.dueHours},after}]};
  act('Contract offer edited',s=>s.events.push({id:S.uid(),label:'Contract offer edit',hours:s.hours,offer:structuredClone(edited)}));
  contractDrafts=contractDrafts.map(x=>x.offerId===id?edited:x);render();
 });
}
function accountsPanel(){return panel('Bank & ledger',`<div class="panel-body toolbar">${btn('Record expense','expense','',true)}${btn('Referee bank correction','bank-correct','',true)}${btn('Export backup','export')}</div>${table(['Hour','World','Entry','Amount',''],[...state.ledger].reverse().map(l=>`<tr><td>${l.hours}</td><td>${esc(world(l.world)?.name||'Setup')}</td><td>${esc(l.type)}</td><td class="number ${A.credit(l.amount)<0n?'bad':'good'}">${money(l.amount)}</td><td>${btn('Details','ledger-audit',l.id,false,'small')}</td></tr>`),'large-scroll')}`);}
function historyPanel(){return panel('Action history',`<div class="panel-body row">${btn('Undo latest change','undo','',true,'primary')}<span class="help">Undo restores bank, cargo, route, contracts and policy state together.</span></div>${[...state.events].reverse().map(e=>`<div class="history-item">${esc(e.label)}<div class="muted">Hour ${e.hours??'—'} · ${esc(world(e.world)?.name||'Campaign')} ${e.reason?'· '+esc(e.reason):''}</div>${btn('Details','event-audit',e.id,false,'small')}</div>`).join('')||empty('Your committed actions appear here.')}`);}
function settingsPanel(){return panel('Campaign controls',`<div class="panel-body"><div class="split"><div><h3>${esc(state.name)}</h3><p class="help">${esc(state.ship.name)} · Jump ${state.ship.jump} · ${esc(state.ship.capacity)} tons</p><p>Profit mode: <strong>${state.settings.profit===100?'RAW':state.settings.profit===75?'Reduced':'Custom'} ${state.settings.profit}%</strong></p><p class="help">Tax ${state.settings.tax?'on':'off'} · Insurance ${state.settings.insurance?'on':'off'}</p></div><div class="wide-actions">${btn('Ship, trader & options','settings-edit','',true)}${btn('Advance / correct time','time','',true)}${btn('Rules & Notes','notes')}</div></div><hr><p class="help">Browser storage is local to this device and browser. Export a backup before moving devices or clearing browser data.</p><div class="wide-actions">${btn('Export backup','export')}${btn('Import backup','import','',true)}${btn('Reset campaign','reset','',true,'danger')}</div></div>`);}
async function setup(){let picker;modal('Start your campaign',`<div class="split">${field('name','Campaign name','My trading campaign')}${field('ship','Ship name','Independent trader')}${field('bank','Opening bank · Cr','100000')}${field('capacity','Cargo capacity · tons','60')}${field('jump','Jump rating','2','number','min="1" max="6"')}${field('date','Starting Imperial date · day-year','001-1105')}</div><div id="setup-world"></div>${check('scoops','Ship has fuel scoops',true)}<p class="help">Existing cargo is added separately and will not debit this opening bank.</p>`,async f=>{const w=await picker.resolve();known[w.id]=w;parseDate(f.get('date'));const bank=A.credit(f.get('bank'));if(bank<0n)throw Error('Opening bank cannot be negative');act('Campaign setup',s=>{s.initialized=true;s.name=f.get('name');s.ship.name=f.get('ship');s.ship.capacity=A.decimal(f.get('capacity'));s.ship.jump=Number(f.get('jump'));s.ship.scoops=f.has('scoops');s.bank=String(bank);s.dateLabel=f.get('date');s.actual=w.id;s.worlds[w.id]=w;s.route=[w.id];s.ledger.push({id:S.uid(),type:'Opening bank',amount:String(bank),hours:0,world:w.id});});view=w.id;await refreshNearby(false);},'Start campaign');picker=createWorldPicker($('setup-world'),{initial:{sector:'Spinward Marches',hex:'1910'},title:'Current world'});}
async function refreshNearby(show=true){const w=viewed();if(!w)return;const rows=await M.nearby(w,12);rows.forEach(x=>known[x.id]=x);render();if(show)message('Live nearby worlds loaded.');}
function findWorld(){
 let picker;
 modal('Find a world','<div id="find-world"></div><p class="help">Browse to inspect this world, or use it as your ship’s starting position.</p><button type="button" id="choose-starting-world">Use as starting world</button>',async()=>{
  const w=await picker.resolve();known[w.id]=w;view=w.id;await refreshNearby(false);
 },'Browse world');
 picker=createWorldPicker($('find-world'),{initial:viewed()||{sector:'Spinward Marches',hex:'1910'}});
 $('choose-starting-world').onclick=async()=>{const b=$('choose-starting-world');b.disabled=true;try{const w=await picker.resolve();known[w.id]=w;setLocation(w);}catch(e){$('modal-error').textContent=e.message;}finally{b.disabled=false;}};
}
function overrideWorld(id){const w=world(id);modal('World override · '+w.name,`${field('uwp','Effective UWP',w.overrideUWP||w.uwp)}<p class="help">Original Traveller Map UWP: ${esc(w.uwp)}</p>${select('zone','Travel zone',[['Safe','Safe'],['Amber','Amber'],['Red','Red']],w.zone)}${select('fuel','Fuel availability',[['auto','Use known facilities / ship scoops'],['yes','Referee: fuel available'],['no','Referee: unavailable']],w.fuelOverride===true?'yes':w.fuelOverride===false?'no':'auto')}${check('water','Accessible water suitable for fuel collection',w.accessibleWater)}${field('reason','Reason for override','')}`,f=>{R.parseUWP(f.get('uwp'),core);if(!f.get('reason').trim())throw Error('Reason required');act('World override',s=>{s.worlds[id]={...w,overrideUWP:f.get('uwp').toUpperCase(),zone:f.get('zone'),fuelOverride:f.get('fuel')==='yes'?true:f.get('fuel')==='no'?false:null,accessibleWater:f.has('water'),overrideReason:f.get('reason')};});});}
function plotRoute(){
 const origin=actual(),previous=(state.mandatoryStops||[]).map(id=>world(id)).filter(Boolean);
 const destination=previous.at(-1)||(viewed()?.id!==origin.id?viewed():{sector:origin.sector,subsector:M.subsectorForHex(origin.hex)});
 let destinationPicker;const stopRows=[];
 modal('Plan route · fewest jumps',`<div class="route-origin"><span class="eyebrow">Starting world · ship's actual location</span><p><strong>${esc(origin.name)}</strong> · ${esc(origin.sector)} · Hex ${esc(origin.hex)}</p></div><div id="route-stops"></div><button type="button" id="add-route-stop">Add stop</button><div id="route-destination"></div><p class="help">Searches up to 12 parsecs around each requested stop. Ties use least distance, then stable world IDs. Planning does not move the ship.</p>`,async()=>{
  const revision=modalRevision;
  // Capture every selection before making requests; incomplete dropdowns cannot submit an old world.
  const selections=[...stopRows.map(row=>row.picker.selection()),destinationPicker.selection()];
  const stops=[origin];for(const choice of selections){const w=await M.loadWorld(choice.sector,choice.hex);rememberWorld(w);known[w.id]=w;stops.push(w);}
  for(const w of stops){for(const x of await M.nearby(w,12))known[x.id]=x;}
  const all={...known,...state.worlds},path=M.plan(all,stops.map(w=>w.id),state.ship,core);
  const distance=path.slice(1).reduce((n,id,i)=>n+M.distance(all[path[i]],all[id]),0);
  modal('Review route',`<p>${path.map(id=>esc(all[id].name)).join(' → ')}</p><div class="preview"><dl><dt>Jumps</dt><dd>${path.length-1}</dd><dt>Total distance</dt><dd>${distance} pc</dd></dl></div><p class="help">Changing the plan does not move the ship. Insurance keeps its original route until amended.</p>`,()=>act('Route planned',s=>{s.worlds={...all};s.route=[...s.route.slice(0,s.routeIndex),...path];s.mandatoryStops=stops.slice(1).map(w=>w.id);},revision),'Save route');return false;
 },'Calculate route');
 function arrange(){
  stopRows.forEach((row,i)=>{row.title.textContent='Stop '+(i+1);row.up.disabled=i===0;row.down.disabled=i===stopRows.length-1;$('route-stops').append(row.element);});
 }
 function addStop(initial={sector:origin.sector,subsector:M.subsectorForHex(origin.hex)}){
  const element=document.createElement('section');element.className='route-stop';
  const title=document.createElement('h3'),actions=document.createElement('div');actions.className='row';
  const host=document.createElement('div');element.append(title,actions,host);$('route-stops').append(element);
  const row={element,title,picker:createWorldPicker(host,{initial,title:'Stop world'})};
  for(const [label,key,offset] of [['Move up','up',-1],['Move down','down',1],['Remove stop','remove',0]]){
   const button=document.createElement('button');button.type='button';button.textContent=label;row[key]=button;actions.append(button);
   button.onclick=()=>{const i=stopRows.indexOf(row);if(!offset){stopRows.splice(i,1);element.remove();}else{const j=i+offset;if(j<0||j>=stopRows.length)return;[stopRows[i],stopRows[j]]=[stopRows[j],stopRows[i]];}arrange();};
  }
  stopRows.push(row);arrange();
 }
 $('add-route-stop').onclick=()=>addStop();
 for(const w of previous.slice(0,-1))addStop(w);
 destinationPicker=createWorldPicker($('route-destination'),{initial:destination,title:'Destination world'});
}
function jump(){const to=world(state.route[state.routeIndex+1]);if(!to)throw Error('Plan a route first');const from=actual(),distance=M.distance(from,to);if(distance>state.ship.jump||!M.fuel(from,state.ship,core)||!M.fuel(to,state.ship,core))throw Error('Route leg is no longer valid for this ship and fuel availability.');const dice=R.roll(6),hours=148+dice.total;modal('Commit jump · '+from.name+' → '+to.name,`<div class="preview"><dl><dt>Distance</dt><dd>${distance} pc</dd><dt>Jump dice</dt><dd>${dice.dice.join(' + ')}</dd><dt>Elapsed time</dt><dd>${hours} hours</dd></dl></div>${field('hours','Elapsed hours · referee override',hours,'number','min="0" step="1"')}<p class="help">This moves the ship and advances time. A policy covering a different route requires an amendment before it covers the changed route.</p>`,f=>{const elapsed=Number(f.get('hours'));if(!Number.isSafeInteger(elapsed)||elapsed<0)throw Error('Enter whole nonnegative hours');act('Jump: '+from.name+' → '+to.name,s=>{if(s.actual!==from.id)throw Error('Actual world changed');s.actual=to.id;s.routeIndex++;s.hours+=elapsed;s.events.push({id:S.uid(),label:'Jump audit',from:from.id,to:to.id,dice,generatedHours:hours,effectiveHours:elapsed,hours:s.hours});for(const p of s.policies.filter(p=>p.status==='active')){const i=p.routeProgress||0;if(p.route?.[i]!==from.id||p.route?.[i+1]!==to.id)p.status='amendment-required';else{p.routeProgress=i+1;if(p.destination===to.id)p.status='arrived';}}});view=to.id;render();},'COMMIT JUMP');}
function searchDialog(kind='supplier'){if(viewed()?.id!==state.actual)throw Error('Search at the ship’s actual world.');const c=ctx(state.actual),dice=R.roll(2),time=R.roll(1),brokerDice=R.roll(2),localSkill=Math.floor(brokerDice.total/3);const previous=state.snapshots.filter(s=>s.worldId===state.actual&&state.hours>=s.startedHours&&state.hours-s.startedHours<720).length;modal('Find a '+kind,`<p class="help">${esc(actual().name)} · previous attempts in 30 days: ${previous} (DM −${previous}). Search duration advances campaign time only when committed.</p><div class="split">${field('party',kind==='buyer'?'Buyer identity':'Supplier identity',(kind==='buyer'?'Buyer ':'Supplier ')+(previous+1))}${select('method','Search method',[['normal','Broker · 1D days'],['blackMarket','Streetwise / black market · 1D days'],['online','Online Admin · 1D hours (TL8+)']],'normal')}${field('dice','Search 2D total',dice.total,'number','min="2" max="12"')}${field('duration','Duration die (1–6)',time.total,'number','min="1" max="6"')}${field('characteristic','EDU / SOC DM',state.trader.characteristic,'number','step="1"')}${field('counterparty','Counterparty Broker skill',2,'number','step="1"')}</div>${check('local','Hire a local broker / fixer')}${field('localSkill','Local skill: 2D ÷ 3, rounded down',localSkill,'number','min="0" step="1"')}<p class="help">Local skill dice: ${brokerDice.dice.join(' + ')}. Negotiations use local skill +2; normal fee 10%, illegal trade 20%. A natural 2 for a fixer is flagged for the referee.</p>${check('success','Referee override: treat this search as successful')}`,f=>{const method=f.get('method'),m=core.search.methods[method];if(method==='online'&&(c.uwp.techLevel===null||c.uwp.techLevel<8))throw Error('Online search requires TL8+');const partyName=f.get('party').trim();if(!partyName)throw Error('Counterparty identity required');const key=partyKey(state.actual,partyName);if((state.cooldowns[key]||0)>state.hours)throw Error('This counterparty is still in rejection cooldown.');const useLocal=f.has('local'),skill=useLocal&&method!=='online'?Number(f.get('localSkill')):Number(state.trader[m.skill.toLowerCase()]),rolled=Number(f.get('dice')),duration=Number(f.get('duration')),characteristic=Number(f.get('characteristic')),counterparty=Number(f.get('counterparty'));if(![skill,rolled,duration,characteristic,counterparty].every(Number.isInteger)||rolled<2||rolled>12||duration<1||duration>6)throw Error('Invalid search input');const port=core.search.starportDM[c.uwp.starport]||0,total=rolled+skill+characteristic+port-previous,success=total>=8||f.has('success'),illegal=method==='blackMarket',hours=duration*(m.durationUnit==='days'?24:1);const options={illegal,skill:useLocal?Number(f.get('localSkill')):state.trader.broker,local:useLocal,counterparty};const offers=success&&kind==='supplier'?R.market(c,options,core).map(o=>({...o,id:S.uid(),remaining:o.quantity,expired:false,illegal:!!good(o.commodity).universallyIllegal,description:good(o.commodity).name,original:{quantity:o.quantity,unitPrice:o.unitPrice}})):[];const snap={id:S.uid(),kind,party:key,partyName,worldId:state.actual,world:c,startedHours:state.hours,hours:state.hours+hours,criminal:illegal,options,offers,success,rulesVersion:R.VERSION,interpretationVersion:1,search:{generatedDice:dice,effectiveTotal:rolled,skill,characteristic,port,previous,total,difficulty:8,successOverride:f.has('success'),durationDie:duration,hours,localSkillDice:useLocal?brokerDice:null,fixerWarning:useLocal&&illegal&&brokerDice.total===2}};modal('Review '+kind+' search',`<div class="preview"><dl><dt>Search total / target</dt><dd>${total} / 8</dd><dt>Result</dt><dd>${success?'Contact found':'No contact found'}</dd><dt>Elapsed time</dt><dd>${hours} hours</dd><dt>Goods offered</dt><dd>${offers.length}</dd></dl></div>${snap.search.fixerWarning?'<p class="notice">Natural 2: the fixer may be an informer. Referee adjudication required.</p>':''}<p class="help">Committing records this attempt and its elapsed time. It does not buy or sell cargo.</p>`,()=>{act(kind+' search: '+partyName,s=>{s.hours+=hours;s.snapshots.push(snap);});snapshotId=snap.id;if(kind==='buyer'&&success){saleForm(snap);return false;}},'Commit search');return false;},'Preview search');}
function findOffer(id){for(const snap of state.snapshots){const offer=snap.offers.find(o=>o.id===id);if(offer)return {snap,offer};}throw Error('Offer missing');}
function commodityAudit(id){const {snap,offer}=findOffer(id),a=offer.audit,g=good(offer.commodity);const dmRows=[];for(const [label,part,sign]of [['Purchase modifiers',a.purchase,1],['Sale modifiers',a.sale,-1]]){if(!part)continue;dmRows.push(`<tr><td>${label}</td><td>${(part.applicable||[]).map(x=>esc(x.code)+' '+(x.value>=0?'+':'')+x.value).join(', ')||'None'}</td><td class="number">${part.selected}</td><td class="number">${sign*part.selected}</td></tr>`);}modal('Commodity audit · '+offer.description,`<p class="help">${esc(snap.world.world.name)} · frozen UWP ${esc(snap.world.uwp.raw)} · codes ${snap.world.codes.join(', ')}. Core Rulebook pp. 242–245.</p>${table(['Modifier group','Matches','Largest only','Applied to purchase'],dmRows)}<div class="preview"><dl><dt>Price roll</dt><dd>${a.dice?.dice?.join(' + ')||'Manual'} = ${a.dice?.total??'—'}</dd><dt>Trader / broker skill</dt><dd>${a.skill??'—'}</dd><dt>Local broker bonus</dt><dd>${a.localDM??0}</dd><dt>Counterparty skill subtracted</dt><dd>${a.counterparty??'—'}</dd><dt>Modified result</dt><dd>${a.modified??'—'}</dd><dt>Price table result</dt><dd>${a.tableResult??'—'}</dd><dt>Base price × percentage</dt><dd>${g.baseCreditsPerTon===null?'Referee':money(g.baseCreditsPerTon)+' × '+(a.percent??'—')+'%'}</dd><dt>Original price / ton</dt><dd>${money(offer.original?.unitPrice??0)}</dd><dt>Effective price / ton</dt><dd class="total">${money(offer.unitPrice)}</dd></dl></div><h3>Availability</h3><p class="help">${g.common?'Common stock':`Matching availability: ${g.availabilityAny.filter(x=>snap.world.codes.includes(x)).join(', ')||'random/referee only'}`} · extra random draws: ${(a.randomDraws||[]).filter(x=>x===g.id).length}</p>${table(['Quantity dice','Population DM','Multiplier','Tons'],(a.quantityRolls||[]).map(q=>`<tr><td>${q.dice.join(' + ')}</td><td>${q.populationDM}</td><td>× ${q.multiplier}</td><td>${q.tons}</td></tr>`))}<p class="help">Remaining quantity: ${esc(offer.remaining)} t. ${offer.expired?'Expired':'Active'}${offer.expirationNote?' · '+esc(offer.expirationNote):''}</p><p><a href="${ROOT}RULES_VERIFICATION.md" target="_blank" rel="noopener">Rules verification</a> · <a href="${ROOT}RULES_REVIEW.md#interpretation-decision-register" target="_blank" rel="noopener">Broker and market interpretations</a></p><details><summary>Overrides and full saved evidence</summary><pre>${esc(JSON.stringify({overrides:offer.overrides||[],previousAudits:offer.previousAudits||[],original:offer.original,audit:a},null,2))}</pre></details>`,null);}
function editOffer(id){const {snap,offer}=findOffer(id);modal('Referee market override',`<p>${esc(offer.description)}</p><div class="split">${field('quantity','Remaining tons',offer.remaining)}${field('price','Price per ton · Cr',offer.unitPrice)}</div>${field('roll','Pricing 3D total · optional override',offer.audit.dice?.total||10,'number','step="1"')}${check('useRoll','Recalculate price from this roll instead of the price field')}${field('expirationNote','Expiration / date note',offer.expirationNote||'')}${field('description','Description',offer.description)}${check('illegal','Illegal on this world',offer.illegal)}${field('reason','Reason','')}`,f=>{if(!f.get('reason').trim()||A.cmp(f.get('quantity'),0)<0||A.cmp(f.get('price'),0)<0)throw Error('Valid values and reason required');const recalculated=f.has('useRoll')?R.quote(good(offer.commodity),snap.world,{...snap.options,side:'buy',rollTotal:Number(f.get('roll'))},core):null;act('Market override',s=>{const o=s.snapshots.find(x=>x.id===snap.id).offers.find(x=>x.id===id);o.overrides??=[];o.overrides.push({hours:s.hours,reason:f.get('reason'),before:{remaining:o.remaining,unitPrice:o.unitPrice},after:{remaining:A.decimal(f.get('quantity')),unitPrice:A.decimal(f.get('price'))}});o.remaining=A.decimal(f.get('quantity'));o.unitPrice=recalculated?recalculated.unitPrice:A.decimal(f.get('price'));if(recalculated){o.previousAudits??=[];o.previousAudits.push(o.audit);o.audit={...o.audit,...recalculated.audit};}o.expirationNote=f.get('expirationNote');o.description=f.get('description');o.illegal=f.has('illegal');o.manualRequired=false;});});}
function buyForm(id){const {snap,offer}=findOffer(id);S.assertWorld(state,snap.worldId);if(offer.expired||offer.manualRequired)throw Error('Offer is expired or needs referee values.');const defaultFee=snap.options.local?(offer.illegal?20:10):0;modal('Purchase · '+offer.description,`<div class="split">${field('quantity','Tons to buy',A.cmp(offer.remaining,1)<0?offer.remaining:'1')}${field('fee','Broker fee · %',defaultFee,'number','min="0" max="100" step="any"')}</div>${field('description','Cargo-lot description',offer.description)}<p class="help">Price: ${money(offer.unitPrice)} per ton. Each purchase creates a separate lot.</p>${state.settings.insurance?`${check('insure','Insure this cargo')}${select('coverage','Coverage',mp.insurance.coveragePercent.map(x=>[x,x+'%']),70)}${field('manualPremium','Referee premium · Cr (required beyond 6 pc; blank uses table)','')}<p class="help">Uses the remaining planned route and its destination. Route changes require an amendment.</p>`:''}`,f=>{const quantity=A.positive(f.get('quantity'),'Quantity'),feePercent=Number(f.get('fee'));const cost=A.floor(A.mul(quantity,offer.unitPrice)),fee=A.floor(A.mul(cost,A.div(feePercent,100)));let insurance=null;if(f.has('insure')){const route=state.route.slice(state.routeIndex);if(route.length<2)throw Error('Plan the insured route and destination first');const distance=route.slice(1).reduce((n,x,i)=>n+M.distance(world(route[i]),world(x)),0);insurance={...R.insuranceQuote(cost,Number(f.get('coverage')),distance,route.map(x=>world(x).zone),mp,f.get('manualPremium').trim()||null),route,destination:route.at(-1),routeProgress:0};}const args={snapshotId:snap.id,offerId:id,quantity,feePercent,description:f.get('description'),insurance};S.buy(structuredClone(state),args);modal('Confirm purchase',`<div class="preview"><dl><dt>Cargo</dt><dd>${esc(quantity)} t</dd><dt>Goods</dt><dd>${money(cost)}</dd><dt>Broker fee</dt><dd>${money(fee)}</dd><dt>Insurance premium</dt><dd>${money(insurance?.premium||0)}</dd><dt>Total debit</dt><dd class="total">${money(cost+fee+A.credit(insurance?.premium||0))}</dd></dl></div>${insurance?`<p class="help">${insurance.coverage}% coverage to ${esc(world(insurance.destination).name)}. Potential payout ${money(insurance.potentialPayout)}. Claims require referee approval.</p>`:''}`,()=>act('Purchase: '+args.description,s=>S.buy(s,args)),'COMMIT PURCHASE');return false;},'Preview purchase');}
function saleForm(buyer){if(!selected.size)throw Error('Select at least one cargo lot');S.assertWorld(state,buyer.worldId);const c=ctx(state.actual),lots=state.lots.filter(l=>selected.has(l.id));if(lots.some(l=>l.illegal)&&!buyer.criminal)throw Error('Illegal cargo needs a black-market buyer.');const quotes={};for(const l of lots){try{quotes[l.id]=R.quote(good(l.commodity),c,{...buyer.options,side:'sell'},core);}catch(e){quotes[l.id]={unitPrice:'0',audit:{manualRequired:true,reason:e.message}};}}for(const l of lots)saleQuotes.set(l.id,{...quotes[l.id],worldId:state.actual,revision:state.revision,buyerId:buyer.id});render();modal('Prepare sale · '+buyer.partyName,`<p class="help">One committed sale sets one tax bracket. Each lot retains its actual cost and separate profit adjustment. ${buyer.criminal?'Criminal market: no automatic tax.':''}</p>${lots.map(l=>`<div class="preview"><h3>${esc(l.description)}</h3><div class="split">${field('qty_'+l.id,'Tons to sell',l.quantity)}${field('price_'+l.id,'Sale price / ton · Cr',quotes[l.id].unitPrice)}${field('benchmark_'+l.id,'Normal market value / ton · Cr',good(l.commodity).baseCreditsPerTon??'')}${field('ban_'+l.id,'Local ban Law Level (blank if not applicable)','')}</div><p class="help">Remaining actual cost: ${money(l.basis)}. Price can be overridden. Local ban threshold is a referee input.</p></div>`).join('')}<div class="split">${field('fee','Total broker fee · %',buyer.options.local?(lots.some(l=>l.illegal)?20:10):0,'number','min="0" max="100" step="any"')}${field('taxRate','Referee tax rate · % (blank uses table)','','number','min="0" max="100" step="any"')}</div>${field('reason','Reason for manual price / benchmark / tax overrides','')}`,f=>{const lines=lots.map(l=>{let price=f.get('price_'+l.id);const threshold=f.get('ban_'+l.id).trim();if(threshold&&Number(threshold)<=c.uwp.law&&!buyer.criminal)throw Error('Locally banned cargo needs a black-market buyer.');let q=quotes[l.id];if(threshold){q=R.quote(good(l.commodity),c,{...buyer.options,side:'sell',rollTotal:q.audit.dice?.total,banThreshold:Number(threshold)},core);if(price===quotes[l.id].unitPrice)price=q.unitPrice;}const benchmark=f.get('benchmark_'+l.id),manual=price!==q.unitPrice||benchmark!==String(good(l.commodity).baseCreditsPerTon)||f.get('taxRate').trim()||q.audit.manualRequired;if(manual&&!f.get('reason').trim())throw Error('Add a reason for manual values');return {lotId:l.id,quantity:f.get('qty_'+l.id),unitPrice:price,benchmarkPrice:benchmark,audit:{...q.audit,manualPrice:price!==q.unitPrice?price:null,overrideReason:f.get('reason'),banThreshold:threshold||null}};});const p=R.salePreview(state.lots,lines,{percent:state.settings.profit,feePercent:Number(f.get('fee')),government:c.uwp.government===null?'?':core.uwp.numericAlphabet[c.uwp.government],criminal:buyer.criminal,taxEnabled:state.settings.tax,manualTaxRate:f.get('taxRate').trim()===''?null:Number(f.get('taxRate'))},core,mp);for(const line of p.lines)saleQuotes.set(line.lotId,{unitPrice:line.unitPrice,audit:line.audit,worldId:state.actual,revision:state.revision,buyerId:buyer.id});render();previewSale={...p,worldId:state.actual,party:buyer.party,revision:state.revision};modal('Confirm sale',`${table(['Lot','RAW profit','Tax','After tax','Adjusted profit'],p.lines.map(l=>`<tr><td>${esc(l.description)}</td><td class="number">${money(l.raw)}</td><td class="number">${money(l.tax)}</td><td class="number">${money(l.afterTax)}</td><td class="number">${money(l.adjusted)}</td></tr>`))}<div class="preview"><dl><dt>Gross sale</dt><dd>${money(p.gross)}</dd><dt>Broker fees</dt><dd>${money(p.fee)}</dd><dt>Tax · ${p.tax.rate}%</dt><dd>${money(p.tax.amount)}</dd><dt>Bank credit</dt><dd class="total">${money(p.bankDelta)}</dd></dl></div><details><summary>Full calculation audit</summary><pre>${esc(JSON.stringify(p,null,2))}</pre></details><p class="help"><a href="${ROOT}RULES_VERIFICATION.md" target="_blank" rel="noopener">Rules verification</a> · INT-007–021 · Cost is not debited again.</p>`,()=>{act('Sale to '+buyer.partyName,s=>S.sell(s,p,buyer.worldId,buyer.party),previewSale.revision);selected.clear();render();},'COMMIT SALE');return false;},'Preview sale');}
function beginSale(){if(!selected.size)throw Error('Select cargo first');if(viewed()?.id!==state.actual)throw Error('Return to the ship’s actual world to sell');const buyers=state.snapshots.filter(s=>s.kind==='buyer'&&s.worldId===state.actual&&s.success&&(state.cooldowns[s.party]||0)<=state.hours);if(!buyers.length){searchDialog('buyer');return;}modal('Choose a buyer',`${select('buyer','Previous buyer',buyers.map(b=>[b.id,b.partyName+' · hour '+b.hours]),buyers.at(-1).id)}<p class="help">Previously found buyers remain usable unless rejected. A fresh negotiation generates a new price.</p>${btn('Find another buyer','buyer-search','',true)}${buyers.length?btn('Reject selected buyer','reject',buyers.at(-1).id,true):''}`,f=>{saleForm(buyers.find(b=>b.id===f.get('buyer')));return false;},'Negotiate sale');}
function reject(snapId){const snap=state.snapshots.find(s=>s.id===snapId);modal('Reject this deal?',`<p>${esc(snap.partyName)} will be unavailable for 30 days (720 hours). Browsing away does not trigger this restriction.</p>`,()=>act('Rejected '+snap.partyName,s=>{s.cooldowns[snap.party]=s.hours+720;}),'Reject deal');}
function existingLot(){modal('Add existing / referee cargo',`${select('commodity','Commodity',core.commodities.map(g=>[g.id,g.name]),'11')}${field('description','Description','Existing cargo')}<div class="split">${field('quantity','Tons','1')}${field('basis','Remaining actual cost · Cr (including fees/premium)','0')}${field('goods','Remaining goods purchase value · Cr (excluding fees)','0')}${field('reason','Reason','Opening cargo')}</div>${check('illegal','Illegal cargo')}<p class="help">This adds owned cargo without changing the bank. All values are recorded for future partial sales.</p>`,f=>act('Cargo added',s=>S.addLot(s,{commodity:f.get('commodity'),description:f.get('description'),quantity:f.get('quantity'),basis:f.get('basis'),goodsValue:f.get('goods'),illegal:f.has('illegal')},f.get('reason'),f.get('reason')==='Opening cargo')));}
function correctCargo(id){const l=state.lots.find(l=>l.id===id);modal('Correct cargo · '+l.description,`<div class="split">${field('quantity','Remaining tons',l.quantity)}${field('description','Lot description',l.description)}${field('basis','Remaining actual cost · Cr',l.basis)}${field('goods','Remaining goods purchase value · Cr',l.goodsValue)}${field('reason','Required reason','')}</div><p class="help">Zero quantity removes the lot only when both remaining values are zero. This is not a sale or insurance claim.</p>`,f=>act('Cargo correction',s=>{S.correctLot(s,id,f.get('quantity'),f.get('basis'),f.get('goods'),f.get('reason'));const lot=s.lots.find(x=>x.id===id);if(lot){lot.description=f.get('description');s.events.at(-1).after=structuredClone(lot);}} ));}
function claimForm(id){const p=state.policies.find(p=>p.id===id);modal('Record insured loss',`<p class="help">Remaining insured cargo: ${esc(p.remainingQuantity)} t; goods value ${money(p.remainingValue)}. Coverage ${p.coverage}%.</p>${field('quantity','Lost insured tons','1')}${field('reason','Loss / evidence description','')}${check('approved','Referee has approved this loss and claim')}`,f=>{const args={policyId:id,quantity:f.get('quantity'),reason:f.get('reason'),approved:f.has('approved')};const test=structuredClone(state);S.claim(test,args);const result=test.policies.find(p=>p.id===id).claims.at(-1);modal('Confirm loss and claim',`<div class="preview"><dl><dt>Cargo removed</dt><dd>${esc(result.quantity)} t</dd><dt>Cost written off</dt><dd>${money(result.basisWrittenOff)}</dd><dt>Claim payout</dt><dd class="total">${money(result.payout)}</dd></dl></div><p class="help">Tax and profit reduction do not apply. This removes the lost cargo and records the payout together.</p>`,()=>act('Insurance claim',s=>S.claim(s,args)),'Commit loss & claim');return false;},'Preview claim');}
function amendPolicy(id){const p=state.policies.find(p=>p.id===id);modal('Amend insurance policy',`${select('mode','Action',[['amend','Cover current remaining planned route'],['close','Close remaining coverage']], 'amend')}${field('adjustment','Premium adjustment · Cr (negative = refund)','0')}${field('reason','Amendment reason','')}${check('approved','Referee approves the amended terms')}<p class="help">Original terms stay in the audit. Premium adjustments change both the bank and remaining lot cost basis.</p>`,f=>{if(!f.has('approved')||!f.get('reason').trim())throw Error('Referee approval and reason required');const adjustment=A.credit(f.get('adjustment')),route=state.route.slice(state.routeIndex);if(f.get('mode')==='amend'&&route.length<2)throw Error('Plan a remaining route first');act('Insurance amended',s=>{const policy=s.policies.find(x=>x.id===id),lot=s.lots.find(x=>x.id===policy.lotId);if(!lot||A.cmp(policy.remainingQuantity,0)<=0)throw Error('No remaining insured cargo');if(A.credit(s.bank)<adjustment||A.credit(lot.basis)+adjustment<0n)throw Error('Invalid premium adjustment');policy.amendments.push({hours:s.hours,reason:f.get('reason'),previous:{route:policy.route,destination:policy.destination,status:policy.status},adjustment:String(adjustment)});s.bank=String(A.credit(s.bank)-adjustment);lot.basis=String(A.credit(lot.basis)+adjustment);s.ledger.push({id:S.uid(),type:'Insurance amendment',amount:String(-adjustment),policyId:id,reason:f.get('reason'),hours:s.hours,world:s.actual});if(f.get('mode')==='close'){policy.status='closed';policy.remainingQuantity='0';policy.remainingValue='0';}else{policy.route=route;policy.routeProgress=0;policy.destination=route.at(-1);policy.status='active';}});});}
function contractSearch(){if(viewed()?.id!==state.actual)throw Error('Search at the actual world');const destinations=Object.values({...known,...state.worlds}).filter(w=>w.id!==state.actual).sort((a,b)=>a.name.localeCompare(b.name));if(!destinations.length)throw Error('Load nearby worlds or a destination first');const dice=R.roll(2);modal('Find freight & mail',`${select('destination','Destination',destinations.map(w=>[w.id,w.name+' · '+w.hex]),state.route[state.routeIndex+1]||destinations[0].id)}<div class="split">${field('dice','Search 2D total',dice.total,'number','min="2" max="12"')}${field('skill','Broker / Streetwise skill',Math.max(state.trader.broker,state.trader.streetwise),'number','step="1"')}${field('characteristic','Search characteristic DM',state.trader.characteristic,'number','step="1"')}${field('days','Freight deadline · days from now','14','number','min="0" step="1"')}</div><details><summary>Override freight / mail dice</summary>${field('diceSequence','Optional dice in roll order (1–6, comma-separated)','')}<p class="help">Order: major, minor, incidental traffic (2 dice), then lot-count dice and each lot’s tonnage die; finally mail availability (2 dice) and container count. Unspecified dice roll normally; every result is saved.</p></details><p class="help">Enter the referee-agreed deadline; 14 days is an editable suggestion, not a rulebook deadline. Generated contracts use direct origin-to-destination parsecs from the map; use a manual contract for different terms.</p>`,f=>{const destination=f.get('destination'),to=world(destination),distance=M.distance(actual(),to),effect=Number(f.get('dice'))+Number(f.get('skill'))+Number(f.get('characteristic'))-8,days=Number(f.get('days'));if(!Number.isSafeInteger(days)||days<0)throw Error('Enter whole nonnegative days');const manualDice=f.get('diceSequence').trim()?f.get('diceSequence').split(',').map(x=>Number(x.trim())):[];if(manualDice.some(x=>!Number.isInteger(x)||x<1||x>6))throw Error('Dice overrides must be numbers 1–6');let usedDice=0;const rng=()=>usedDice<manualDice.length?manualDice[usedDice++]:R.die();const a=ctx(state.actual),b=R.context(to,core),freight=R.freightOffers(a,b,distance,effect,core,rng),mail=R.mailOffer(a,b,distance,effect,state.ship,state.trader,core,rng);const generated=[...freight,...(mail.available?[mail]:[])].map(o=>({...o,offerId:S.uid(),origin:state.actual,destination,dueHours:o.kind==='mail'?null:state.hours+days*24,generatedHours:state.hours,rulesVersion:R.VERSION}));act('Contract search',s=>{s.events.push({id:S.uid(),label:'Contract search audit',hours:s.hours,destination,searchDice:dice,effectiveSearchDice:Number(f.get('dice')),effect,manualDice,manualDiceConsumed:usedDice,mailAudit:mail.audit,offers:structuredClone(generated)});});contractDrafts=generated;tab='Contracts';render();message(generated.length+' contract offers generated. '+(!mail.available?'No mail available this search.':''));},'Generate offers');}
function manualContract(){const destinations=Object.values({...known,...state.worlds}).filter(w=>w.id!==state.actual);modal('Manual freight / mail contract',`${select('kind','Kind',[['freight','Freight'],['mail','Mail']],'freight')}${select('destination','Destination',destinations.map(w=>[w.id,w.name]),destinations[0]?.id)}<div class="split">${field('quantity','Whole contract · tons','5')}${field('payment','Payment on delivery · Cr','1000')}${field('days','Due in days (freight)','14','number','min="0" step="1"')}${field('reason','Referee terms / reason','')}</div>`,f=>{if(!f.get('reason').trim())throw Error('Reason required');const c={offerId:S.uid(),kind:f.get('kind'),origin:state.actual,destination:f.get('destination'),quantity:A.positive(f.get('quantity')),payment:String(A.credit(f.get('payment'))),dueHours:f.get('kind')==='mail'?null:state.hours+Number(f.get('days'))*24,audit:{manual:true,reason:f.get('reason')},rulesVersion:R.VERSION};act('Manual contract accepted',s=>S.acceptContract(s,c));});}
function accept(id){const c=contractDrafts.find(c=>c.offerId===id);if(!c)throw Error('Offer no longer available');modal('Accept '+c.kind,`<p>${esc(c.quantity)} tons to ${esc(world(c.destination).name)}, paying ${money(c.payment)} on delivery.</p><p class="help">The entire contract must fit. This reserves capacity; it does not pay you yet.</p>`,()=>{act('Accepted '+c.kind,s=>S.acceptContract(s,c));contractDrafts=contractDrafts.filter(x=>x.offerId!==id);render();},'Accept whole contract');}
function deliver(id){const c=state.contracts.find(c=>c.id===id);S.assertWorld(state,c.destination);const late=c.kind==='freight'&&c.dueHours!==null&&state.hours>c.dueHours,d=R.roll(1);modal('Deliver '+c.kind,`<p>Destination: ${esc(world(c.destination).name)} · ${esc(c.quantity)} tons · contracted ${money(c.payment)}</p>${late?`<p class="notice">Late delivery: payment is reduced by (1D + 4) × 10%.</p>${field('die','Penalty die',d.total,'number','min="1" max="6"')}`:'<p class="help">Full payment is due. Tax and profit reduction do not apply.</p>'}`,f=>act('Delivered '+c.kind,s=>S.deliver(s,id,late?Number(f.get('die')):1)),'Commit delivery & payout');}
function expenseForm(correction=false){modal(correction?'Referee bank correction':'Record expense',`${field('amount',correction?'Bank change · Cr (negative removes money)':'Expense · Cr','0')}${field('reason','Description / reason','')}`,f=>act(correction?'Bank correction':'Manual expense',s=>correction?S.bankCorrection(s,f.get('amount'),f.get('reason')):S.expense(s,f.get('amount'),f.get('reason'))));}
function settings(){modal('Ship, trader & options',`<div class="split">${field('name','Campaign',state.name)}${field('ship','Ship name',state.ship.name)}${field('capacity','Cargo capacity · tons',state.ship.capacity)}${field('jump','Jump rating',state.ship.jump,'number','min="1" max="6"')}${field('broker','Broker skill',state.trader.broker,'number','step="1"')}${field('streetwise','Streetwise skill',state.trader.streetwise,'number','step="1"')}${field('admin','Admin skill',state.trader.admin,'number','step="1"')}${field('characteristic','Default EDU / SOC DM',state.trader.characteristic,'number','step="1"')}${field('rank','Highest Naval / Scout rank',state.trader.rank,'number','min="0" step="1"')}${field('soc','Highest SOC DM',state.trader.soc,'number','step="1"')}${select('mode','Profit mode',[['100','RAW · 100%'],['75','Reduced · 75%'],['custom','Custom']],state.settings.profit===75||state.settings.profit===100?String(state.settings.profit):'custom')}${field('custom','Custom positive-profit percentage',state.settings.profit,'number','min="0" max="100" step="any"')}</div>${check('scoops','Fuel scoops fitted',state.ship.scoops)}${check('armed','Ship is armed (mail modifier)',state.ship.armed)}${check('tax','Enable optional Merchant Prince taxes',state.settings.tax)}${check('insurance','Enable optional Merchant Prince cargo insurance',state.settings.insurance)}<p class="help">Options affect future transactions. Existing policy terms and historical results are preserved.</p>`,f=>act('Ship / trader settings',s=>{s.name=f.get('name');s.ship={name:f.get('ship'),capacity:A.decimal(f.get('capacity')),jump:Number(f.get('jump')),scoops:f.has('scoops'),armed:f.has('armed')};for(const key of ['broker','streetwise','admin','characteristic','rank','soc']){const n=Number(f.get(key));if(!Number.isInteger(n))throw Error('Skills and DMs must be whole numbers');s.trader[key]=n;}s.settings={profit:Number(f.get('mode')==='custom'?f.get('custom'):f.get('mode')),tax:f.has('tax'),insurance:f.has('insurance')};}));}
function timeForm(){modal('Campaign time',`${field('date','Starting Imperial date · day-year',state.dateLabel)}${field('hours','Total elapsed hours from starting date',state.hours,'number','min="0" step="1"')}${field('reason','Reason for time change','')}`,f=>{if(!f.get('reason').trim())throw Error('Reason required');parseDate(f.get('date'));act('Time correction: '+f.get('reason'),s=>{s.dateLabel=f.get('date');s.hours=Number(f.get('hours'));});});}
function notes(){modal('Rules & Notes',`<div class="notes-list"><article><h3>Rules and verification</h3><p>Application 0.1.0 · rules data ${R.VERSION}. Source/data checks: 198 passing. Runtime test results are recorded in the public verification record.</p><p>Traveller Core Rulebook Update 2022, examined copyright 2024 revision. Merchant Prince: Mongoose Traveller 1st Edition, Book 7; insurance p. 83, taxes p. 86. Optional first-edition adaptations are off by default.</p><p><a href="${ROOT}RULES_VERIFICATION.md" target="_blank" rel="noopener">Rules verification status and evidence</a> · <a href="${ROOT}rules/README.md" target="_blank" rel="noopener">Sources and worked examples</a></p></article><article><h3>House rules</h3><p>RAW retains 100% of positive actual profit; Reduced retains 75%; Custom accepts 0–100%. Tax is deducted first. Losses are unchanged by the profit setting. Each lot is adjusted separately. Final posted money rounds down; fractional tons are preserved. Operating expenses remain separate.</p></article>${decisions.map(d=>`<article id="${esc(d.id)}"><h3>${esc(d.id)} · ${esc(d.topic)}</h3><p>${esc(d.conclusion)}</p><p class="help">Agreed ${esc(d.date)} · revision ${d.revision}</p></article>`).join('')}<article><h3>Copyright and credits</h3><p>Traveller and the source publications are owned by Mongoose Publishing and their respective rights holders. This is an unofficial campaign tool, not a publisher-endorsed product. Rulebook PDFs, scans and descriptive source prose are not distributed with this tool.</p><p>Live world data: <a href="https://travellermap.com" target="_blank" rel="noopener">Traveller Map</a>. Source and calculation references are retained for review. The existing spec-trade tool is not a rules authority.</p></article><article><h3>Calendar and map era</h3><p>World data stays in the M1105 era. The campaign starts at its chosen Imperial day-year date, default 001-1105, and advances in 24-hour days and 365-day years as searches and jumps consume time. Advancing the campaign year never switches map eras. Browsing, route previews and setting a starting world do not advance time.</p></article><article><h3>About your data</h3><p>Your campaign stays in this browser’s local storage. Export JSON backups to keep a portable copy. Traveller Map requests disclose the worlds/sectors being requested; campaign bank and cargo data are not sent to it. Route searches cover a bounded loaded area and do not simulate fuel consumption.</p></article></div>`,null);}
function backupReplace(title,next){modal(title,`<p class="notice">This replaces the current campaign in this browser. Export a backup before continuing.</p><div class="wide-actions">${btn('Export current backup','export')}</div>${check('backed','I saved a backup, or explicitly choose to proceed without one')}<p class="help">Cancel keeps the current campaign. The replacement is validated before it is saved.</p>`,f=>{if(!f.has('backed'))throw Error('Export a backup or explicitly choose to proceed without one');store.replace(next,modalRevision);known={...next.worlds};view=next.actual;selected.clear();contractDrafts=[];render();message('Campaign replaced.');},'Replace campaign');}
function zoomMap(factor,reset=false){
 mapZoom=reset?1:Math.max(.2,Math.min(2.4,mapZoom*factor));
 if(!mapZoomFrame)mapZoomFrame=requestAnimationFrame(()=>{mapZoomFrame=0;const action=document.activeElement?.dataset.action;render();if(action?.startsWith('map-zoom-'))document.querySelector('[data-action="'+action+'"]')?.focus({preventScroll:true});});
}
function setLocation(w){
 if(typeof w==='string')w=world(w);
 if(!w)throw Error('Choose a world first');
 if(w.id===state.actual){view=w.id;return refreshNearby().catch(e=>message('Could not refresh nearby worlds: '+e.message,true));}
 const from=actual();
 modal('Set ship location',`<p>Use <strong>${esc(w.name)}</strong> · ${esc(w.sector)} · Hex ${esc(w.hex)} as the ship’s actual location?</p><p class="notice">This sets or corrects your starting position. It does not simulate a jump or advance time. The current route will be cleared. Bank, cargo and contract payments stay unchanged. Active insurance will require a route amendment.</p>${field('reason','Reason',state.hours===0&&state.lots.length===0?'Choose campaign starting world':'')}`,async f=>{
  const reason=f.get('reason').trim();if(!reason)throw Error('Enter a reason for changing the ship location.');
  const revision=modalRevision;
  const neighbors=await M.nearby(w,12);
  neighbors.forEach(x=>known[x.id]=x);
  act('Ship location set: '+w.name,s=>{s.worlds[w.id]=w;s.actual=w.id;s.route=[w.id];s.routeIndex=0;s.mandatoryStops=[];s.events.push({id:S.uid(),label:'Starting-world / location correction',from:from?.id||null,to:w.id,reason,hours:s.hours});for(const p of s.policies.filter(p=>p.status==='active'))p.status='amendment-required';},revision);
  view=w.id;contractDrafts=[];render();
 },'Confirm starting world');
}
document.addEventListener('wheel',e=>{
 if(e.ctrlKey||!e.target.closest?.('.world-map')||$('modal').open)return;
 e.preventDefault();const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?320:1);
 if(delta)zoomMap(Math.exp(-Math.max(-200,Math.min(200,delta))*.002));
},{passive:false});
const actions={'map-zoom-in':()=>zoomMap(1.2),'map-zoom-out':()=>zoomMap(1/1.2),'map-zoom-reset':()=>zoomMap(1,true),'set-location':setLocation,tab:id=>{tab=id;render();},notes,setup,find:findWorld,nearby:()=>refreshNearby(),world:id=>{view=id;render();},'browse-prev':()=>{const i=state.route.indexOf(view||state.actual);view=state.route[Math.max(0,i-1)]||state.actual;render();},'browse-next':()=>{const i=state.route.indexOf(view||state.actual);view=state.route[Math.min(state.route.length-1,i+1)]||state.actual;render();},override:overrideWorld,route:plotRoute,jump,search:()=>searchDialog(),'buyer-search':()=>searchDialog('buyer'),buy:buyForm,'offer-edit':editOffer,'offer-audit':commodityAudit,'expire-all':id=>act('Expired all snapshot offers',s=>s.snapshots.find(x=>x.id===id).offers.forEach(o=>o.expired=true)),reject,sale:beginSale,'add-lot':existingLot,'lot-correct':correctCargo,'lot-sell':id=>{selected=new Set([id]);beginSale();},'lot-audit':lotAudit,'policy-audit':id=>audit('Insurance policy',state.policies.find(p=>p.id===id)),claim:claimForm,amend:amendPolicy,'contracts-search':contractSearch,'contract-manual':manualContract,'contract-accept':accept,'draft-edit':editDraft,'draft-audit':id=>audit('Contract offer',contractDrafts.find(c=>c.offerId===id)),'contract-audit':id=>audit('Contract',state.contracts.find(c=>c.id===id)),deliver,expense:()=>expenseForm(),'bank-correct':()=>expenseForm(true),'ledger-audit':id=>audit('Ledger entry',state.ledger.find(l=>l.id===id)),'event-audit':id=>audit('History entry',state.events.find(e=>e.id===id)),undo:()=>{store.save(S.undo(state),state.revision);message('Latest action undone.');},'settings-edit':settings,time:timeForm,export:()=>{store.backup();message('Backup download requested. Check that the file was saved.');},import:()=>$('import-file').click(),reset:()=>backupReplace('Reset campaign',S.initial())};
document.addEventListener('click',safely(async e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){e.preventDefault();await actions[b.dataset.action]?.(b.dataset.arg);}}));
document.addEventListener('keydown',safely(e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [data-action]')){e.preventDefault();actions[e.target.dataset.action]?.(e.target.dataset.arg);}}));
document.addEventListener('change',safely(e=>{const t=e.target;if(t.id==='map-hexes'){showHexes=t.checked;render();}if(t.dataset.expire){const {snap}=findOffer(t.dataset.expire);act(t.checked?'Offer expired':'Offer reactivated',s=>s.snapshots.find(x=>x.id===snap.id).offers.find(o=>o.id===t.dataset.expire).expired=t.checked);}if(t.dataset.lot){t.checked?selected.add(t.dataset.lot):selected.delete(t.dataset.lot);render();}if(t.id==='market-filter'){marketFilter=t.value;render();}if(t.id==='snapshot-select'){snapshotId=t.value;render();}if(t.id==='cargo-sort'){cargoSort=t.value;render();}}));
document.addEventListener('input',e=>{if(!['market-search','cargo-search'].includes(e.target.id))return;const id=e.target.id,pos=e.target.selectionStart;if(id==='market-search')marketSearch=e.target.value;else cargoSearch=e.target.value;render();$(id)?.focus();$(id)?.setSelectionRange(pos,pos);});
$('modal-close').onclick=()=> $('modal').close();$('modal-cancel').onclick=()=> $('modal').close();$('notes').onclick=safely(notes);$('takeover').onclick=safely(()=>store.acquire(true));
$('import-file').onchange=safely(async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>20000000)throw Error('Import exceeds the 20 MB review limit');const data=S.validate(JSON.parse(await file.text()));backupReplace('Import campaign',data);});
async function boot(){[core,mp,decisions]=await Promise.all(['rules/core-2022.json','rules/merchant-prince-1e.json','rules/decisions.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('Could not load '+url);return r.json();}));store=new Store(s=>{state=s;known={...known,...s.worlds};view??=s.actual;render();},(editable,text)=>{$('save-status').textContent=text;$('save-status').className=editable?'muted':'readonly';$('takeover').hidden=editable;render();});try{state=store.read();}catch(error){store.recovery=true;store.recoveryMessage=error.message;state=S.initial();}known={...state.worlds};view=state.actual;render();await store.acquire();if(state.initialized)refreshNearby(false).catch(e=>message('Could not load nearby worlds: '+e.message+'. Use Refresh nearby to retry.',true));}
boot().catch(e=>{message(e.message,true);$('main').innerHTML=empty('The calculator could not start. Your saved campaign has not been replaced. Reload after checking the error above.');});
